COPY unidad_intervencion_18.lc_anexotipo (t_id, thisclass, baseclass, itfcode, ilicode, seq, inactive, dispname, description) FROM stdin;
633	Modelo_Aplicacion_LADMCOL_Lev_Cat_V1_2.LC_AnexoTipo	\N	0	Enramadas_Cobertizos_Caneyes.Tipo_90	\N	f	(Enramadas o cobertizos o caneyes) Tipo 90	Locales de venta de vehículos: Estructura concreto, cubierta cercha metálica y teja canaleta; fachada vidrio y polarizado, piso baldosín conservación general buena.
634	Modelo_Aplicacion_LADMCOL_Lev_Cat_V1_2.LC_AnexoTipo	\N	1	Enramadas_Cobertizos_Caneyes.Tipo_80	\N	f	(Enramadas o cobertizos o caneyes) Tipo 80	Estructura metálica; cubierta de zinc, eternit o teja de barro, pisos de cemento, conservación general buena.
635	Modelo_Aplicacion_LADMCOL_Lev_Cat_V1_2.LC_AnexoTipo	\N	2	Enramadas_Cobertizos_Caneyes.Tipo_60	\N	f	(Enramadas o cobertizos o caneyes) Tipo 60	Estructura en madera fina; cubierta de zinc, eternit o teja de barro pisos de cemento; conservación general buena a regular.
