--
-- TOC entry 5908 (class 1259 OID 9850807)
-- Name: vw_validadores_sinic; Type: VIEW; Schema: unidad_intervencion_18; Owner: cc1026287641
--

CREATE VIEW unidad_intervencion_18.vw_validadores_sinic AS
 SELECT DISTINCT 'SINIC'::text AS item,
    lp.t_id AS t_id_predio,
    '2_CLC_CJ_99 Un NPN con posición 22 igual a 3 o 4 debe ser de uso público con dominio'::text AS regla
   FROM ((((unidad_intervencion_18.lc_predio lp
     LEFT JOIN unidad_intervencion_18.lc_derecho ld ON ((ld.unidad = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_interesado li ON (((li.local_id)::text = (lp.t_id)::text)))
     LEFT JOIN unidad_intervencion_18.lc_datosadicionaleslevantamientocatastral ld2 ON ((ld2.lc_predio = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_estructuranovedadnumeropredial le ON ((le.lc_dtsdcnlstmntctstral_novedad_numeros_prediales = ld2.t_id)))
  WHERE (("substring"((lp.numero_predial)::text, 22, 1) = ANY (ARRAY['3'::text, '4'::text])) AND ((lp.tipo <> 109) OR (ld.tipo <> 122)))
UNION ALL
 SELECT DISTINCT 'SINIC'::text AS item,
    lp.t_id AS t_id_predio,
    '2_CLC_CJ_96 Un predio formal fiscal/patrimonial con dominio debe contar con FMI'::text AS regla
   FROM ((((unidad_intervencion_18.lc_predio lp
     LEFT JOIN unidad_intervencion_18.lc_derecho ld ON ((ld.unidad = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_interesado li ON (((li.local_id)::text = (lp.t_id)::text)))
     LEFT JOIN unidad_intervencion_18.lc_datosadicionaleslevantamientocatastral ld2 ON ((ld2.lc_predio = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_estructuranovedadnumeropredial le ON ((le.lc_dtsdcnlstmntctstral_novedad_numeros_prediales = ld2.t_id)))
  WHERE ((lp.tipo = 108) AND (ld.tipo = 122) AND (lp.matricula_inmobiliaria IS NULL))
UNION ALL
 SELECT DISTINCT '05 derecho'::text AS item,
    lp.t_id AS t_id_predio,
    'no deben existir predios con tipo publico fiscal '::text AS regla
   FROM ((((unidad_intervencion_18.lc_predio lp
     LEFT JOIN unidad_intervencion_18.lc_derecho ld ON ((ld.unidad = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_interesado li ON (((li.local_id)::text = (lp.t_id)::text)))
     LEFT JOIN unidad_intervencion_18.lc_datosadicionaleslevantamientocatastral ld2 ON ((ld2.lc_predio = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_estructuranovedadnumeropredial le ON ((le.lc_dtsdcnlstmntctstral_novedad_numeros_prediales = ld2.t_id)))
  WHERE (lp.tipo = 107)
UNION ALL
 SELECT DISTINCT 'SINIC'::text AS item,
    lp.t_id AS t_id_predio,
    '2_CLC_CJ_88 Un predio privado con dominio debe tener un FMI positivo'::text AS regla
   FROM ((((unidad_intervencion_18.lc_predio lp
     LEFT JOIN unidad_intervencion_18.lc_derecho ld ON ((ld.unidad = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_interesado li ON (((li.local_id)::text = (lp.t_id)::text)))
     LEFT JOIN unidad_intervencion_18.lc_datosadicionaleslevantamientocatastral ld2 ON ((ld2.lc_predio = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_estructuranovedadnumeropredial le ON ((le.lc_dtsdcnlstmntctstral_novedad_numeros_prediales = ld2.t_id)))
  WHERE (((le.tipo_novedad <> 154) OR (le.tipo_novedad IS NULL)) AND (lp.tipo = 111) AND (ld.tipo = 122) AND (lp.matricula_inmobiliaria IS NULL))
UNION ALL
 SELECT DISTINCT 'SINIC'::text AS item,
    lp.t_id AS t_id_predio,
    '2_CLC_CJ_88 Un predio privado con dominio debe tener un FMI positivo'::text AS regla
   FROM ((((unidad_intervencion_18.lc_predio lp
     LEFT JOIN unidad_intervencion_18.lc_derecho ld ON ((ld.unidad = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_interesado li ON (((li.local_id)::text = (lp.t_id)::text)))
     LEFT JOIN unidad_intervencion_18.lc_datosadicionaleslevantamientocatastral ld2 ON ((ld2.lc_predio = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_estructuranovedadnumeropredial le ON ((le.lc_dtsdcnlstmntctstral_novedad_numeros_prediales = ld2.t_id)))
  WHERE (((le.tipo_novedad <> 154) OR (le.tipo_novedad IS NULL)) AND (lp.tipo = 111) AND (ld.tipo = 122) AND (lp.matricula_inmobiliaria IS NULL))
UNION ALL
 SELECT DISTINCT 'SINIC'::text AS item,
    lp.t_id AS t_id_predio,
    '2_CLI_CJ_72 Una persona jurídica debe contar con un documento de NIT'::text AS regla
   FROM ((((unidad_intervencion_18.lc_predio lp
     LEFT JOIN unidad_intervencion_18.lc_derecho ld ON ((ld.unidad = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_interesado li ON (((li.local_id)::text = (lp.t_id)::text)))
     LEFT JOIN unidad_intervencion_18.lc_datosadicionaleslevantamientocatastral ld2 ON ((ld2.lc_predio = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_estructuranovedadnumeropredial le ON ((le.lc_dtsdcnlstmntctstral_novedad_numeros_prediales = ld2.t_id)))
  WHERE ((li.tipo = 130) AND (li.tipo_documento <> ALL (ARRAY[(133)::bigint, (138)::bigint])) AND (NOT ((li.tipo_documento = 136) AND ((li.documento_identidad)::text <> '0'::text))))
UNION ALL
 SELECT DISTINCT 'SINIC'::text AS item,
    lp.t_id AS t_id_predio,
    '2_CLI_CJ_71 Una persona natural no puede tener un NIT'::text AS regla
   FROM ((((unidad_intervencion_18.lc_predio lp
     LEFT JOIN unidad_intervencion_18.lc_derecho ld ON ((ld.unidad = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_interesado li ON (((li.local_id)::text = (lp.t_id)::text)))
     LEFT JOIN unidad_intervencion_18.lc_datosadicionaleslevantamientocatastral ld2 ON ((ld2.lc_predio = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_estructuranovedadnumeropredial le ON ((le.lc_dtsdcnlstmntctstral_novedad_numeros_prediales = ld2.t_id)))
  WHERE ((li.tipo = 129) AND (li.tipo_documento = 133))
UNION ALL
 SELECT DISTINCT 'SINIC'::text AS item,
    lp.t_id AS t_id_predio,
    '2_CLD_CJ_66 El derecho de dominio solo puede recaer sobre un predio formal'::text AS regla
   FROM ((((unidad_intervencion_18.lc_predio lp
     LEFT JOIN unidad_intervencion_18.lc_derecho ld ON ((ld.unidad = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_interesado li ON (((li.local_id)::text = (lp.t_id)::text)))
     LEFT JOIN unidad_intervencion_18.lc_datosadicionaleslevantamientocatastral ld2 ON ((ld2.lc_predio = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_estructuranovedadnumeropredial le ON ((le.lc_dtsdcnlstmntctstral_novedad_numeros_prediales = ld2.t_id)))
  WHERE ((ld.tipo = 122) AND ("substring"((lp.numero_predial)::text, 22, 1) = '2'::text))
UNION ALL
 SELECT DISTINCT 'SINIC'::text AS item,
    lp.t_id AS t_id_predio,
    '3.2 Las unidades de construcción asociadas a predios matrices de PH y Condominios (Zonas comunes) se les asociará el tipo de dominio “común”. Para lo restante se asociará el tipo de dominio “Privado”.'::text AS regla
   FROM ((((((unidad_intervencion_18.lc_predio lp
     LEFT JOIN unidad_intervencion_18.lc_derecho ld ON ((ld.unidad = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_interesado li ON (((li.local_id)::text = (lp.t_id)::text)))
     LEFT JOIN unidad_intervencion_18.lc_datosadicionaleslevantamientocatastral ld2 ON ((ld2.lc_predio = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_estructuranovedadnumeropredial le ON ((le.lc_dtsdcnlstmntctstral_novedad_numeros_prediales = ld2.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_unidadconstruccion lu ON (((lu.etiqueta)::text = (lp.t_id)::text)))
     LEFT JOIN unidad_intervencion_18.lc_caracteristicasunidadconstruccion lc ON ((lc.t_id = lu.lc_caracteristicasunidadconstruccion)))
  WHERE ((lp.condicion_predio = ANY (ARRAY[(351)::bigint, (353)::bigint])) AND (lu.t_id IS NOT NULL) AND (lc.tipo_dominio <> 244))
UNION ALL
 SELECT DISTINCT 'SINIC'::text AS item,
    lp.t_id AS t_id_predio,
    '3.3 Para las unidades asociadas a predios en PH y condominio, las unidades convencionales calificadas deben relacionar usos establecidos específicamente para PH'::text AS regla
   FROM ((((((unidad_intervencion_18.lc_predio lp
     LEFT JOIN unidad_intervencion_18.lc_derecho ld ON ((ld.unidad = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_interesado li ON (((li.local_id)::text = (lp.t_id)::text)))
     LEFT JOIN unidad_intervencion_18.lc_datosadicionaleslevantamientocatastral ld2 ON ((ld2.lc_predio = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_estructuranovedadnumeropredial le ON ((le.lc_dtsdcnlstmntctstral_novedad_numeros_prediales = ld2.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_unidadconstruccion lu ON (((lu.etiqueta)::text = (lp.t_id)::text)))
     LEFT JOIN unidad_intervencion_18.lc_caracteristicasunidadconstruccion lc ON ((lc.t_id = lu.lc_caracteristicasunidadconstruccion)))
  WHERE ((lp.condicion_predio = ANY (ARRAY[(352)::bigint, (354)::bigint])) AND (lu.t_id IS NOT NULL) AND (lc.uso <> ALL (ARRAY[(519)::bigint, (526)::bigint, (531)::bigint, (533)::bigint, (535)::bigint, (537)::bigint, (357)::bigint, (541)::bigint, (544)::bigint, (547)::bigint, (550)::bigint, (555)::bigint, (557)::bigint, (559)::bigint, (561)::bigint, (574)::bigint, (622)::bigint, (619)::bigint, (584)::bigint, (524)::bigint, (605)::bigint, (527)::bigint, (612)::bigint, (593)::bigint, (540)::bigint])))
UNION ALL
 SELECT DISTINCT 'SINIC'::text AS item,
    lp.t_id AS t_id_predio,
    '3.4 Para las unidades asociadas a predios con condición de propiedad diferente a PH o condominio, las unidades convencionales calificadas deben relacionar usos diferentes a PH.'::text AS regla
   FROM (((((((unidad_intervencion_18.lc_predio lp
     LEFT JOIN unidad_intervencion_18.lc_derecho ld ON ((ld.unidad = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_interesado li ON (((li.local_id)::text = (lp.t_id)::text)))
     LEFT JOIN unidad_intervencion_18.lc_datosadicionaleslevantamientocatastral ld2 ON ((ld2.lc_predio = lp.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_estructuranovedadnumeropredial le ON ((le.lc_dtsdcnlstmntctstral_novedad_numeros_prediales = ld2.t_id)))
     LEFT JOIN unidad_intervencion_18.lc_unidadconstruccion lu ON (((lu.etiqueta)::text = (lp.t_id)::text)))
     LEFT JOIN unidad_intervencion_18.lc_caracteristicasunidadconstruccion lc ON ((lc.t_id = lu.lc_caracteristicasunidadconstruccion)))
     LEFT JOIN unidad_intervencion_18.lc_usouconstipo lu2 ON ((lu2.t_id = lc.uso)))
